head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[content > P > scope]<br/>ID 및 전역 객체명의 중복 방지를 위해 Scope 기능을 활성화합니다.",
    "validation" : [
        "frameMode=wframePreload 인 경우에 동작합니다.",     
        "config.xml 의 wframe 항목에 scope=true 로 설정되어 있으면 false 가 적용되지 않습니다.",   
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        scope: con_scope.getText(),
        frameMode: "wframePreload"
    };

    let cList = $c.gcm.createCList(properties);       

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="config.xml 의 wframe 항목에 scope=true 로 설정되어 있는 상태"', '', 'label1');

    strTarget += '<w2:tabControl ' + strNameSpace + ' id="" alwaysDraw="false" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';    
    strTarget += '<w2:content ' + cList + ' src="/sample/common_link/tabControl_link_1.xml" alwaysDraw="true" style="height:160px;" id="content1">';    
    strTarget += '</w2:content>';
    strTarget += '<w2:content ' + cList + ' src="/sample/common_link/tabControl_link_1.xml" alwaysDraw="true" style="height:160px" id="content2">';    
    strTarget += '</w2:content>';    
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );    

    scwin.btn_getID_onclick();
}



scwin.btn_getID_onclick = function (e) {
    setTimeout(() => {  
        let contents = document.querySelectorAll('button[id*="target1_contents_content"]');

        if (contents.length > 0) {
            for (var i=0; i < contents.length; i++)
                wf_body_bottom.getObj("scwin").setReturnValue("contents["+i+"].id : " + contents[i].id);
        }
    }, 100);
};
